cd /workspace; cat > quality/dispositions.py <<'EOF'
"""Disposition rates by window and stratum.

`inspection_results.disposition` is written at inspection time from the reading the measuring machine
produced, against the drawing tolerance in `drawing_limits`. These helpers count it back out, and also
re-disposition readings against the drawing's conformance reference (QP-07 §3): the reading with the
measuring machine's offset removed, the offset being established by the retained-artefact programme (QP-07 §5).
"""
import sqlite3
from statistics import mean, stdev


PRE_WINDOW = (13, 18)
POST_WINDOW = (19, 24)

# two-sided 95 % Student-t critical value for 19 degrees of freedom (20 artefacts)
T_CRIT_19 = 2.093


def connect(db_path):
    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    return con


def tolerance_um(con):
    row = con.execute(
        "SELECT tol_um FROM drawing_limits WHERE part_number='MAN-4471' AND feature='BORE_DIA_42'"
    ).fetchone()
    return float(row["tol_um"])


def parts(con, window):
    lo, hi = window
    return con.execute(
        "SELECT r.*, h.family AS heat_family, h.hardness_hv FROM inspection_results r "
        "JOIN heats h ON h.heat_id = r.heat_id WHERE r.week BETWEEN ? AND ? ORDER BY r.part_id",
        (lo, hi),
    ).fetchall()


def machines(con):
    return [r[0] for r in con.execute("SELECT DISTINCT machine_id FROM inspection_results ORDER BY 1")]


def nonconforming_rate_pct(rows):
    if not rows:
        return None
    bad = sum(1 for r in rows if r["disposition"] == "FAIL")
    return 100.0 * bad / len(rows)


def is_conforming(deviation_um, tol_um):
    # conforming when the deviation lies within +/- tol (inclusive); round away float noise from the offset
    return abs(round(deviation_um, 6)) <= tol_um


def artefact_offset(con, machine_id, date_lo, date_hi):
    """Feature offset of `machine_id` from the retained-artefact rounds dated within [date_lo, date_hi].

    Per artefact: mean of the repeats minus the certified deviation. The offset is the mean over artefacts,
    with a t statistic on the artefact-level differences. Returns None if there is no round in the range.
    """
    rows = con.execute(
        "SELECT m.artefact_id, AVG(m.measured_um) - p.certified_um AS d "
        "FROM reference_measurements m JOIN reference_parts p ON p.artefact_id = m.artefact_id "
        "WHERE m.machine_id = ? AND m.measured_on BETWEEN ? AND ? "
        "GROUP BY m.artefact_id, m.measured_on ORDER BY m.artefact_id, m.measured_on",
        (machine_id, date_lo, date_hi),
    ).fetchall()
    if not rows:
        return None
    d = [r["d"] for r in rows]
    m = mean(d)
    se = stdev(d) / len(d) ** 0.5 if len(d) > 1 else float("inf")
    dates = [r[0] for r in con.execute(
        "SELECT DISTINCT measured_on FROM reference_measurements WHERE machine_id = ? "
        "AND measured_on BETWEEN ? AND ? ORDER BY 1", (machine_id, date_lo, date_hi))]
    return {"mean_um": m, "se_um": se, "t": m / se if se else float("inf"), "n_artefacts": len(d),
            "rounds": dates}


def window_offsets(con, rows):
    """Offset per machine in force over the inspection dates of `rows`, from the artefact rounds in that span.

    A machine whose artefact offset is not distinguishable from zero (|t| < t_0.975,19) carries no offset.
    A compensation write inside the window after the verifying round would invalidate the round, so that is
    refused rather than silently ignored.
    """
    lo = min(r["inspected_on"] for r in rows)
    hi = max(r["inspected_on"] for r in rows)
    out, detail = {}, {}
    for mc in machines(con):
        est = artefact_offset(con, mc, lo, hi)
        if est is None:
            raise RuntimeError(f"no retained-artefact round for {mc} between {lo} and {hi}")
        later = con.execute(
            "SELECT event_date FROM calibration_events WHERE machine_id = ? AND event_type LIKE '%ADJUST%' "
            "AND event_date > ? AND event_date <= ?", (mc, est["rounds"][-1], hi)).fetchall()
        if later:
            raise RuntimeError(f"{mc} adjusted after its verifying artefact round; offset not established")
        significant = abs(est["t"]) >= T_CRIT_19
        out[mc] = round(est["mean_um"], 2) if significant else 0.0
        detail[mc] = dict(est, significant=significant, window_dates=[lo, hi])
    return out, detail


def corrected(rows, offsets, tol_um):
    """[(row, deviation against the conformance reference, PASS/FAIL)] for each row."""
    out = []
    for r in rows:
        dev = r["measured_um"] - offsets.get(r["machine_id"], 0.0)
        out.append((r, dev, "PASS" if is_conforming(dev, tol_um) else "FAIL"))
    return out


def corrected_rate_pct(corr):
    return 100.0 * sum(1 for _, _, d in corr if d == "FAIL") / len(corr)


def strata_rates(rows):
    keys = {"by_machine": "machine_id", "by_shift": "shift", "by_heat_family": "heat_family",
            "by_operator": "operator_id"}
    out = {}
    for name, col in keys.items():
        groups = {}
        for r in rows:
            groups.setdefault(r[col], []).append(r)
        out[name] = {k: round(nonconforming_rate_pct(v), 2) for k, v in sorted(groups.items())}
    return out
